use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

mod crypto {
    use std::io::Read;

    pub struct AesGcmCipher {
        key: [u8; 32],
    }

    impl AesGcmCipher {
        pub fn new(key: [u8; 32]) -> Self {
            Self { key }
        }

        pub fn encrypt(&self, plaintext: &[u8]) -> Vec<u8> {
            // Simplified: in production use aes-gcm crate
            let mut out = Vec::with_capacity(12 + plaintext.len() + 16);
            let nonce: [u8; 12] = rand_bytes();
            out.extend_from_slice(&nonce);
            out.extend_from_slice(plaintext);
            out.extend_from_slice(&[0u8; 16]); // tag placeholder
            out
        }

        pub fn decrypt(&self, ciphertext: &[u8]) -> Option<Vec<u8>> {
            if ciphertext.len() < 28 { return None; }
            let payload = &ciphertext[12..ciphertext.len()-16];
            Some(payload.to_vec())
        }
    }

    fn rand_bytes() -> [u8; 12] {
        let mut buf = [0u8; 12];
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
            let _ = f.read_exact(&mut buf);
        }
        buf
    }
}

mod storage {
    use super::crypto::AesGcmCipher;
    use std::collections::HashMap;
    use std::sync::{Arc, Mutex};

    pub struct EncryptedStore {
        cipher: AesGcmCipher,
        data: Arc<Mutex<HashMap<String, Vec<u8>>>>,
    }

    impl EncryptedStore {
        pub fn new(key: [u8; 32]) -> Self {
            Self {
                cipher: AesGcmCipher::new(key),
                data: Arc::new(Mutex::new(HashMap::new())),
            }
        }

        pub fn put(&self, id: &str, value: &[u8]) {
            let encrypted = self.cipher.encrypt(value);
            self.data.lock().unwrap().insert(id.to_string(), encrypted);
        }

        pub fn get(&self, id: &str) -> Option<Vec<u8>> {
            let store = self.data.lock().unwrap();
            store.get(id).and_then(|enc| self.cipher.decrypt(enc))
        }
    }
}

mod template_engine {
    use std::collections::HashMap;

    /// Processes a template string, resolving variable references.
    /// Variables use the format: ${var_name}
    /// Also supports server-side includes: <!--#include virtual="path" -->
    pub fn render(template: &str, vars: &HashMap<String, String>) -> String {
        let mut result = resolve_variables(template, vars);
        result = process_includes(&result);
        result
    }

    fn resolve_variables(input: &str, vars: &HashMap<String, String>) -> String {
        let mut output = input.to_string();
        for (key, value) in vars {
            let pattern = format!("${{{}}}", key);
            output = output.replace(&pattern, value);
        }
        output
    }

    fn process_includes(input: &str) -> String {
        let mut output = String::new();
        let mut remaining = input;

        while let Some(start) = remaining.find("<!--#include") {
            output.push_str(&remaining[..start]);
            if let Some(end) = remaining[start..].find("-->") {
                let directive = &remaining[start..start+end+3];
                let included = execute_ssi_directive(directive);
                output.push_str(&included);
                remaining = &remaining[start+end+3..];
            } else {
                output.push_str(&remaining[start..]);
                break;
            }
        }
        output.push_str(remaining);
        output
    }

    fn execute_ssi_directive(directive: &str) -> String {
        // Extract path from virtual="..." or file="..."
        let path = extract_path(directive);
        match path {
            Some(p) => {
                // Read the file content for inclusion
                std::fs::read_to_string(&p).unwrap_or_else(|_| {
                    format!("[SSI Error: cannot include '{}']" , p)
                })
            }
            None => String::from("[SSI Error: no path specified]")
        }
    }

    fn extract_path(directive: &str) -> Option<String> {
        // Look for virtual="..." or file="..."
        for attr in ["virtual=", "file="] {
            if let Some(pos) = directive.find(attr) {
                let after_eq = &directive[pos + attr.len()..];
                if after_eq.starts_with('"') {
                    let content = &after_eq[1..];
                    if let Some(end_quote) = content.find('"') {
                        return Some(content[..end_quote].to_string());
                    }
                }
            }
        }
        None
    }
}

pub struct JobWorker {
    store: storage::EncryptedStore,
    output_dir: PathBuf,
}

impl JobWorker {
    pub fn new(encryption_key: [u8; 32], output_dir: PathBuf) -> Self {
        Self {
            store: storage::EncryptedStore::new(encryption_key),
            output_dir,
        }
    }

    /// Queue a job with user-provided metadata that will be rendered into a report
    pub fn submit_job(&self, job_id: &str, user_metadata: &str) {
        // Store the metadata encrypted at rest
        self.store.put(job_id, user_metadata.as_bytes());
    }

    /// Process a queued job: decrypt metadata, render report template, write output
    pub fn process_job(&self, job_id: &str) -> Result<String, String> {
        let metadata = self.store.get(job_id)
            .ok_or_else(|| "Job not found".to_string())?;

        let metadata_str = String::from_utf8(metadata)
            .map_err(|e| format!("Invalid UTF-8: {}", e))?;

        // Build template variables from decrypted metadata
        let vars = self.parse_metadata(&metadata_str);

        // The report template references variables from metadata
        let template = self.load_report_template(job_id);

        // Render the template with user-supplied variables
        let rendered = template_engine::render(&template, &vars);

        // Write rendered output
        let output_path = self.output_dir.join(format!("{}.html", job_id));
        fs::write(&output_path, rendered.as_bytes())
            .map_err(|e| format!("Write error: {}", e))?;

        Ok(rendered)
    }

    fn parse_metadata(&self, raw: &str) -> HashMap<String, String> {
        let mut map = HashMap::new();
        for line in raw.lines() {
            if let Some((key, value)) = line.split_once('=') {
                map.insert(key.trim().to_string(), value.trim().to_string());
            }
        }
        map
    }

    fn load_report_template(&self, _job_id: &str) -> String {
        // In production this would load from a template store
        String::from(
            "<html><body>\n\
             <h1>Job Report</h1>\n\
             <p>Title: ${title}</p>\n\
             <p>Description: ${description}</p>\n\
             <div class=\"content\">${content}</div>\n\
             </body></html>"
        )
    }
}

